diff --git a/broker/accel/accel.go b/broker/accel/accel.go
new file mode 100644
index 000000000..2b964861f
--- /dev/null
+++ b/broker/accel/accel.go
@@ -0,0 +1,228 @@
+// Package accel discovers accelerators (iGPU, GPU, NPU) and leases them as
+// an admission resource to local inference (SPEC RES-3).
+//
+// Nothing depends on an accelerator: with none present, or with discovery
+// turned off, every lease is a CPU lease and the same service runs on the
+// CPU. A lease never blocks. Leases follow the admission classes (RES-1):
+// foreground takes a device from an experiment, whose lease reports Lost
+// so its next unit of work runs on the CPU; nothing else is taken from.
+//
+// Discovery reads sysfs only (render nodes under class/drm, compute
+// accelerators under class/accel), so it can run on the broker's control
+// path (ARC-2). Opening a device is the inference runtime's business.
+package accel
+
+import (
+	"errors"
+	"fmt"
+	"os"
+	"path/filepath"
+	"sort"
+	"strings"
+	"sync"
+
+	"github.com/ghbmrk/agentos/broker/admission"
+)
+
+// Kind is an accelerator type; kinds combine as a filter.
+type Kind uint8
+
+const (
+	IGPU Kind = 1 << iota // integrated GPU
+	GPU                   // discrete GPU
+	NPU                   // neural processing unit (class/accel)
+
+	Any = IGPU | GPU | NPU
+)
+
+func (k Kind) String() string {
+	switch k {
+	case IGPU:
+		return "igpu"
+	case GPU:
+		return "gpu"
+	case NPU:
+		return "npu"
+	}
+	return fmt.Sprintf("kind(%d)", uint8(k))
+}
+
+// Device is one discovered accelerator.
+type Device struct {
+	Kind   Kind
+	Node   string // device node the inference runtime opens
+	Vendor string // PCI vendor ID, e.g. 0x8086
+	Driver string // kernel driver, e.g. i915, xe, amdgpu, intel_vpu
+}
+
+// Discover lists accelerators under sysRoot (normally /sys): NPUs first,
+// then GPUs by node name. A missing class directory means none of that
+// kind.
+func Discover(sysRoot string) ([]Device, error) {
+	var out []Device
+	for _, c := range []struct {
+		class, prefix, dev string
+	}{
+		{"accel", "accel", "/dev/accel/"},
+		{"drm", "renderD", "/dev/dri/"},
+	} {
+		ents, err := os.ReadDir(filepath.Join(sysRoot, "class", c.class))
+		if errors.Is(err, os.ErrNotExist) {
+			continue
+		}
+		if err != nil {
+			return nil, err
+		}
+		var names []string
+		for _, e := range ents {
+			if strings.HasPrefix(e.Name(), c.prefix) {
+				names = append(names, e.Name())
+			}
+		}
+		sort.Strings(names)
+		for _, name := range names {
+			dev := filepath.Join(sysRoot, "class", c.class, name, "device")
+			d := Device{Node: c.dev + name, Vendor: readTrim(filepath.Join(dev, "vendor"))}
+			if drv, err := os.Readlink(filepath.Join(dev, "driver")); err == nil {
+				d.Driver = filepath.Base(drv)
+			}
+			switch {
+			case c.class == "accel":
+				d.Kind = NPU
+			case integrated(dev):
+				d.Kind = IGPU
+			default:
+				d.Kind = GPU
+			}
+			out = append(out, d)
+		}
+	}
+	return out, nil
+}
+
+// integrated reports a GPU on the root complex's bus 0: Intel iGPUs sit at
+// 0000:00:02.0 and AMD APUs on bus 0 too, while discrete cards hang off a
+// PCIe port on another bus.
+func integrated(dev string) bool {
+	p, err := filepath.EvalSymlinks(dev)
+	if err != nil {
+		return false
+	}
+	return strings.HasPrefix(filepath.Base(p), "0000:00:")
+}
+
+func readTrim(p string) string {
+	b, err := os.ReadFile(p)
+	if err != nil {
+		return ""
+	}
+	return strings.TrimSpace(string(b))
+}
+
+// Pool leases devices. It is safe for concurrent use.
+type Pool struct {
+	mu      sync.Mutex
+	devs    []Device
+	holders []*Lease // per device; nil when free
+}
+
+// NewPool leases devs. A nil or empty list (no accelerator, or discovery
+// turned off) leases only the CPU.
+func NewPool(devs []Device) *Pool {
+	return &Pool{devs: devs, holders: make([]*Lease, len(devs))}
+}
+
+// Lease is one job's claim on a device, or on the CPU.
+type Lease struct {
+	p     *Pool
+	idx   int // -1: CPU
+	owner string
+	class admission.Class
+	lost  chan struct{}
+}
+
+// CPU reports a CPU lease: no device, or the device was taken.
+func (l *Lease) CPU() bool {
+	l.p.mu.Lock()
+	defer l.p.mu.Unlock()
+	return l.idx < 0
+}
+
+// Device is the leased device; zero for a CPU lease.
+func (l *Lease) Device() Device {
+	l.p.mu.Lock()
+	defer l.p.mu.Unlock()
+	if l.idx < 0 {
+		return Device{}
+	}
+	return l.p.devs[l.idx]
+}
+
+// Lost is closed when a higher class takes the device. The holder finishes
+// its current unit and runs the next on the CPU.
+func (l *Lease) Lost() <-chan struct{} { return l.lost }
+
+// Release gives the device back; the lease is a CPU lease afterwards.
+// Releasing a lost or CPU lease frees nothing.
+func (l *Lease) Release() {
+	l.p.mu.Lock()
+	defer l.p.mu.Unlock()
+	if l.idx >= 0 && l.p.holders[l.idx] == l {
+		l.p.holders[l.idx] = nil
+	}
+	l.idx = -1
+}
+
+// Acquire leases a device of one of kinds for owner. It prefers a free
+// device; foreground may take one from an experiment; otherwise the lease
+// is on the CPU. It never blocks or fails.
+func (p *Pool) Acquire(owner string, class admission.Class, kinds Kind) *Lease {
+	l := &Lease{p: p, idx: -1, owner: owner, class: class, lost: make(chan struct{})}
+	p.mu.Lock()
+	defer p.mu.Unlock()
+	victim := -1
+	for i, d := range p.devs {
+		if d.Kind&kinds == 0 {
+			continue
+		}
+		h := p.holders[i]
+		if h == nil {
+			l.idx = i
+			break
+		}
+		if victim < 0 && class == admission.Foreground && h.class == admission.Experiment {
+			victim = i
+		}
+	}
+	if l.idx < 0 && victim >= 0 {
+		close(p.holders[victim].lost)
+		p.holders[victim].idx = -1
+		l.idx = victim
+	}
+	if l.idx >= 0 {
+		p.holders[l.idx] = l
+	}
+	return l
+}
+
+// Summary is STATUS's one line about accelerators.
+func (p *Pool) Summary() string {
+	p.mu.Lock()
+	defer p.mu.Unlock()
+	if len(p.devs) == 0 {
+		return "Accelerators: none; local inference on CPU."
+	}
+	kinds := map[string]bool{}
+	var names []string
+	busy := 0
+	for i, d := range p.devs {
+		if !kinds[d.Kind.String()] {
+			kinds[d.Kind.String()] = true
+			names = append(names, d.Kind.String())
+		}
+		if p.holders[i] != nil {
+			busy++
+		}
+	}
+	return fmt.Sprintf("Accelerators: %d (%s), %d in use.", len(p.devs), strings.Join(names, ", "), busy)
+}
diff --git a/broker/accel/accel_test.go b/broker/accel/accel_test.go
new file mode 100644
index 000000000..fafda6c72
--- /dev/null
+++ b/broker/accel/accel_test.go
@@ -0,0 +1,151 @@
+package accel
+
+import (
+	"os"
+	"path/filepath"
+	"testing"
+
+	"github.com/ghbmrk/agentos/broker/admission"
+)
+
+// REQ: RES-3
+
+// sysfs builds a fake /sys with the given DRM render nodes and accel nodes.
+type node struct{ class, name, vendor, driver, pci string }
+
+func sysfs(t *testing.T, nodes ...node) string {
+	t.Helper()
+	root := t.TempDir()
+	for _, n := range nodes {
+		dev := filepath.Join(root, "devices", "pci0000:00", n.pci)
+		drv := filepath.Join(root, "bus", "pci", "drivers", n.driver)
+		if _, err := os.Stat(dev); err != nil {
+			must(t, os.MkdirAll(dev, 0o755))
+			must(t, os.WriteFile(filepath.Join(dev, "vendor"), []byte(n.vendor+"\n"), 0o644))
+			must(t, os.MkdirAll(drv, 0o755))
+			must(t, os.Symlink(drv, filepath.Join(dev, "driver")))
+		}
+		cls := filepath.Join(root, "class", n.class, n.name)
+		must(t, os.MkdirAll(cls, 0o755))
+		must(t, os.Symlink(dev, filepath.Join(cls, "device")))
+	}
+	return root
+}
+
+func must(t *testing.T, err error) {
+	t.Helper()
+	if err != nil {
+		t.Fatal(err)
+	}
+}
+
+func TestRES3DiscoversIGPUAndNPU(t *testing.T) {
+	root := sysfs(t,
+		node{"drm", "renderD128", "0x8086", "i915", "0000:00:02.0"},
+		node{"drm", "card0", "0x8086", "i915", "0000:00:02.0"}, // a display node, not for compute
+		node{"accel", "accel0", "0x8086", "intel_vpu", "0000:00:0b.0"},
+		node{"drm", "renderD129", "0x10de", "nvidia", "0000:01:00.0"},
+	)
+	devs, err := Discover(root)
+	must(t, err)
+	want := []Device{
+		{Kind: NPU, Node: "/dev/accel/accel0", Vendor: "0x8086", Driver: "intel_vpu"},
+		{Kind: IGPU, Node: "/dev/dri/renderD128", Vendor: "0x8086", Driver: "i915"},
+		{Kind: GPU, Node: "/dev/dri/renderD129", Vendor: "0x10de", Driver: "nvidia"},
+	}
+	if len(devs) != len(want) {
+		t.Fatalf("found %+v", devs)
+	}
+	for i := range want {
+		if devs[i] != want[i] {
+			t.Errorf("device %d = %+v, want %+v", i, devs[i], want[i])
+		}
+	}
+}
+
+// The floor has no accelerator: discovery finds nothing and is not an error.
+func TestRES3NoAcceleratorIsNormal(t *testing.T) {
+	devs, err := Discover(t.TempDir())
+	if err != nil || len(devs) != 0 {
+		t.Fatalf("Discover(empty) = %v, %v", devs, err)
+	}
+	p := NewPool(nil)
+	l := p.Acquire("asr", admission.Foreground, Any)
+	if !l.CPU() {
+		t.Fatalf("lease without accelerators = %+v, want CPU", l)
+	}
+	l.Release()
+}
+
+func TestRES3LeasesAreAnAdmissionResourceAndFallBackToCPU(t *testing.T) {
+	gpu := Device{Kind: IGPU, Node: "/dev/dri/renderD128"}
+	p := NewPool([]Device{gpu})
+	a := p.Acquire("embed", admission.Accepted, Any)
+	if a.CPU() || a.Device() != gpu {
+		t.Fatalf("first lease = %+v, want the iGPU", a)
+	}
+	// Same class: no taking. The second job runs on CPU, same service.
+	b := p.Acquire("embed2", admission.Accepted, Any)
+	if !b.CPU() {
+		t.Fatalf("second lease = %+v, want CPU", b)
+	}
+	a.Release()
+	b.Release()
+	c := p.Acquire("embed3", admission.Accepted, Any)
+	if c.CPU() {
+		t.Fatal("released device not handed out again")
+	}
+	c.Release()
+}
+
+func TestRES1RES3ForegroundTakesTheAcceleratorFromAnExperiment(t *testing.T) {
+	gpu := Device{Kind: IGPU, Node: "/dev/dri/renderD128"}
+	p := NewPool([]Device{gpu})
+	exp := p.Acquire("loop", admission.Experiment, Any)
+	if exp.CPU() {
+		t.Fatal("idle accelerator not lent to an experiment")
+	}
+	call := p.Acquire("asr", admission.Foreground, Any)
+	if call.CPU() || call.Device() != gpu {
+		t.Fatalf("foreground lease = %+v, want the iGPU", call)
+	}
+	select {
+	case <-exp.Lost():
+	default:
+		t.Fatal("experiment not told it lost the device")
+	}
+	// Accepted work is never taken from by anything but foreground, and
+	// foreground never loses a device.
+	call2 := p.Acquire("asr2", admission.Foreground, Any)
+	if !call2.CPU() {
+		t.Fatal("foreground took a device from foreground")
+	}
+	select {
+	case <-call.Lost():
+		t.Fatal("foreground lost its device")
+	default:
+	}
+	exp.Release() // releasing a lost lease frees nothing
+	if p.Acquire("x", admission.Accepted, Any).CPU() == false {
+		t.Fatal("a lost lease's release freed the device foreground holds")
+	}
+}
+
+func TestRES3KindFilterAndDisabledPoolBehaveIdentically(t *testing.T) {
+	npu := Device{Kind: NPU, Node: "/dev/accel/accel0"}
+	p := NewPool([]Device{npu})
+	if l := p.Acquire("gpu-only", admission.Accepted, IGPU|GPU); !l.CPU() {
+		t.Fatalf("NPU handed to a GPU-only job: %+v", l)
+	}
+	// Disabled (A2: identical behavior when disabled): every lease is CPU.
+	off := NewPool(nil)
+	if l := off.Acquire("asr", admission.Foreground, Any); !l.CPU() {
+		t.Fatal("disabled pool handed out a device")
+	}
+	if got := off.Summary(); got != "Accelerators: none; local inference on CPU." {
+		t.Fatalf("summary = %q", got)
+	}
+	if got := p.Summary(); got != "Accelerators: 1 (npu), 0 in use." {
+		t.Fatalf("summary = %q", got)
+	}
+}
diff --git a/broker/budget/ASSUMPTIONS.md b/broker/budget/ASSUMPTIONS.md
new file mode 100644
index 000000000..6c570fef0
--- /dev/null
+++ b/broker/budget/ASSUMPTIONS.md
@@ -0,0 +1,22 @@
+# Resource admission, preemption and budgets: assumptions
+
+Built for PLAN P2-5 (RES-1 to RES-4) on SPEC v0.12 (PR #15), ported from draft #31 as P2-5r and reconciled with PE2 and PE6, on the
+admission controller (P1-2, #19) and the machine lifecycle (P1-4, #23).
+Each row is a reading of the spec, or a gap left for a later package,
+that a reviewer may want to change.
+
+| # | Assumption | Spec basis | If it changes |
+|---|---|---|---|
+| R1 | The floor budget is RES-2's table with GB read as GiB: host 1024, inference 2048, browser 512, headroom 600 MiB, the figures `agentosd` (PE6) and the S1 test kit's `floor_fit` use too; the pool is what is left of `MemTotal`. An 8 GB N95 reports about 7680 MiB, which leaves a 3496 MiB pool: two OpenClaw machines (1552 MiB each), not three. A host whose pool cannot hold the agent machine runs agentosd with the agent off and says so on STATUS (PE6, daemon B15). | RES-2, HW-4, S3, S4 | `budget.Floor`, `budget.OpenClawMB`. |
+| R2 | A larger host keeps every component's budget (HW-4). Its pool grows only until capacity (pool plus headroom) reaches `MaxCapacityMB`, 4500 MiB, the cap PE6 adopted (R1 on #114); HW-4 would allow giving all extra memory to the pool, which needs a measured rule for how many machines a larger host should run. Open question for this package's lens gate. | HW-4, RES-2 | `budget.MaxCapacityMB`, `budget.ForHost`. |
+| R3 | Each component has its own cgroup under one root (`-cgroup-root`, default the broker's own group from `/proc/self/cgroup`; it must be that group or below it, and delegated: systemd's `trusted.delegate`/`user.delegate` mark on the broker's group, or `-cgroup-delegated` with an explicit root. Without that proof the broker writes nothing to the cgroupfs, runs no machines, and STATUS says the memory controls are not set up): `inference`, `browser` and `machines` have hard limits; `broker` has its budget as `memory.min` and no hard limit, so it is never OOM-killed by its own group and its pages are not reclaimed for others. With every other component capped and the headroom left over, the host OOM killer has nothing to choose. The pool's `memory.high` equals its limit; per-machine groups carry the 1/16 throttle (V10). The broker moves itself into `broker` before enabling controllers (cgroup v2 refuses controllers below a group that holds a process). | RES-2 | `budget.Apply`, `agentosd` `openPool`. The P2 unit file sets `Delegate=yes`. |
+| R4 | Host processes outside the broker (systemd, the modem bridge) are not under the root and are covered only by the 1000 MiB host figure; nothing caps them. | RES-2 | Host image (P2-1). |
+| R5 | Preemption never waits for an operation already holding the experiment. `vm.Manager.Preempt` sets a flag, tries the machine's lock, and if a checkpoint, fork, rollback or prune holds it, empties the machine's cgroup (`cgroup.kill`) under that operation; the operation then fails, and the machine is recorded `preempted` once it lets go. While the flag is set, `startFrom` refuses to start the machine, before and after the runtime starts it. Residual window: a sandbox whose start was already inside `runsc` when the kill landed lives until that start returns and its caller stops it, so for up to one start's duration its memory is not counted. | RES-1 | `vm/vm.go` `Preempt`, `startFrom`. |
+| R6 | The preemption target (1 s) is provisional: no DECISIONS.md row freezes it yet. It is measured on CI in a 7680 MiB group with every component loaded (`floor` test): from the foreground request to the experiment's memory being released, idle and mid-checkpoint. Propose freezing it in DECISIONS.md after the N95 run confirms it. CI's cores are faster than the N95's: re-run `floor` on the N95 (A2). | RES-1, A2 | `floor.PreemptTarget`. |
+| R7 | Accelerators are found from sysfs only: `class/accel/accel*` is an NPU, `class/drm/renderD*` a GPU, integrated when it sits on PCI bus 0 (Intel iGPUs at 0000:00:02.0, AMD APUs). Display nodes (`card*`) are not compute devices. | RES-3 | `accel.Discover`. |
+| R8 | An accelerator is an admission resource as a lease, one holder per device. A lease never blocks or fails: with no free device it is a CPU lease, the same service on the CPU. Foreground takes a device from an experiment (the experiment's lease reports `Lost` and its next unit runs on the CPU); nothing else is taken from. `-accel off` makes every lease a CPU lease (A2: identical behavior when disabled). No local inference service exists yet; it takes its leases from this pool. Until it does, `agentosd` builds the pool only to log what it found and keeps no handle: a pool with no lease holders would be dead state on the daemon (L3 on #124). | RES-1, RES-3 | `accel.Pool`; P3 inference. |
+| R9 | The RES-4 reserve is declared per item: a staged release 1280 MiB (S7: 1.0 GiB erofs + 69 MiB verity), journal growth 512 MiB and recall-index growth 1024 MiB (both placeholders until P3 sizes them), 2816 MiB in all. It is the default of `-disk-reserve-mb`, which every snapshot, fork, merge and rollback copy is admitted against (V19). No discretionary download path exists yet; when one does (UPD-3, model downloads) it must pass the same check. | RES-4 | `budget.FloorDisk`. |
+| R10 | Snapshots are pruned by policy every minute: each live machine keeps its newest snapshot, its oldest full checkpoint (the warm template, REV-1), its newest full checkpoint, its 50 newest file-system snapshots and 2 newest full checkpoints. Any snapshot a live machine was forked from is kept (merge needs it), and nothing younger than 10 minutes is pruned (so a fork or merge between taking a snapshot and recording its use never loses it). While free space is below the reserve plus 1 GiB, a machine keeps only the protected ones. A destroyed machine's snapshots are pruned unless a live fork needs one. | RES-4, REV-1, REV-4 | `vm.PrunePolicy`. |
+| R11 | Pruning unpublishes each snapshot (record, then `meta.json`) under the machine's lock, so no rollback, fork or merge of it can pick the snapshot up afterwards, then deletes the files after the locks are released, so a slow delete never holds up a rollback (L3 on #124). A crash mid-delete leaves a directory the next start drops. **Gap:** `Diff` takes no machine lock, and one that resolved a snapshot just before it was unpublished can fail mid-read with not-found; it never reads another snapshot's files, and only snapshots past `MinAge` (10 min) outside every protection are pruned. A per-snapshot reader count that defers deletion would close it. | RES-4 | `vm/prune.go`. |
+| R12 | **Gap: CPU is not budgeted.** Components get memory limits only; no `cpu.weight` is set, so a busy machine pool can starve the broker's CPU and slow STOP and the preemption target (R6) on the N95's four cores. The floor test loads memory, not CPU. Close it by giving `broker` a high `cpu.weight` and `machines` a low one in `Apply`, measured on the N95 run (A2). | RES-1, RES-2 | `budget.Apply`; `floor` test. |
+| R13 | The broker manages cgroups only with proof they are its own: its own group (from `/proc/self/cgroup`) or below, carrying systemd's delegate mark, or an explicit `-cgroup-root` vouched for by `-cgroup-delegated`. Otherwise it writes nothing to the cgroupfs, starts no machines, and STATUS reads "Agent: off, the box's memory controls are not set up; it needs an update." The legacy `-cgroup` flag is gone. | RES-2 | `agentosd` `delegatedRoot`, `openMachines`. |
diff --git a/broker/budget/budget.go b/broker/budget/budget.go
new file mode 100644
index 000000000..f839c34f6
--- /dev/null
+++ b/broker/budget/budget.go
@@ -0,0 +1,152 @@
+// Package budget declares the host's per-component memory budget (SPEC
+// RES-2) and its storage reserve (RES-4), and applies the memory budget
+// with one cgroup v2 group per component.
+//
+// The floor figures are SPEC RES-2's table (from S3 and S4, still to be
+// checked on the N95). A larger host keeps every component's budget and
+// gives the rest to the agent-machine pool, so it adds throughput and
+// changes nothing else (HW-4). All figures are MiB.
+package budget
+
+import (
+	"bufio"
+	"fmt"
+	"os"
+	"path/filepath"
+	"strconv"
+	"strings"
+
+	"github.com/ghbmrk/agentos/broker/admission"
+	"github.com/ghbmrk/agentos/broker/cgroup"
+)
+
+// OpenClawMB is one OpenClaw machine: about 1.6 GB (S4, summed RSS) plus
+// 16 MiB of gVisor overhead (S3).
+const OpenClawMB = 1536 + 16
+
+// Memory is the declared per-component budget, MiB.
+type Memory struct {
+	HostMB      int64 // host image, broker, journal: protected, never capped
+	InferenceMB int64 // local inference (small model, speech, embeddings)
+	BrowserMB   int64 // one credentialed browser
+	HeadroomMB  int64 // never admitted into: S3's no-stall margin
+	PoolMB      int64 // agent machines; set by ForHost
+}
+
+// Floor is RES-2's floor budget, without the pool: 1.0, 2.0 and 0.5 GB
+// read as GiB, the figures agentosd (PE6) and the S1 test kit's floor_fit
+// use too.
+func Floor() Memory {
+	return Memory{HostMB: 1024, InferenceMB: 2048, BrowserMB: 512, HeadroomMB: 600}
+}
+
+// MaxCapacityMB caps admission's capacity (the pool plus headroom) on a
+// large host: agentosd's 4500 MB default before PE6, kept as the cap by
+// PE6 (R1 on #114). HW-4 would let a larger host grow the pool instead;
+// lifting the cap is left to a measured rule (budget R2).
+const MaxCapacityMB = 4500
+
+// ForHost sizes the pool for a host with totalMB of memory: what the
+// declared components leave, with capacity (pool plus headroom) at most
+// MaxCapacityMB. A pool too small for an agent machine is returned as is:
+// the caller turns the agent off and says so (agentosd planMemory).
+func ForHost(totalMB int64, c Memory) (Memory, error) {
+	if c.HostMB <= 0 || c.InferenceMB < 0 || c.BrowserMB < 0 || c.HeadroomMB <= 0 {
+		return Memory{}, fmt.Errorf("budget: every component needs a budget and headroom must be positive: %+v", c)
+	}
+	c.PoolMB = min(totalMB-c.HostMB-c.InferenceMB-c.BrowserMB, MaxCapacityMB) - c.HeadroomMB
+	return c, nil
+}
+
+// Total is the sum of every component and the headroom.
+func (m Memory) Total() int64 {
+	return m.HostMB + m.InferenceMB + m.BrowserMB + m.HeadroomMB + m.PoolMB
+}
+
+// Admission is the admission controller's configuration for the pool: it
+// admits machines into exactly PoolMB and holds the headroom back.
+func (m Memory) Admission() admission.Config {
+	return admission.Config{CapacityMB: m.PoolMB + m.HeadroomMB, HeadroomMB: m.HeadroomMB}
+}
+
+// Groups are the component groups Apply made.
+type Groups struct {
+	Broker, Inference, Browser *cgroup.Group
+	// Machines is opened as a parent: per-machine groups go beneath it.
+	Machines *cgroup.Group
+}
+
+// Apply creates one group per component under root. Inference, the browser
+// and the pool get hard limits; the broker gets its budget as protected
+// memory and no hard limit, so it is never OOM-killed by its own group and
+// its pages are not reclaimed for others. With every other component capped
+// and the headroom left over, the host's own OOM killer has nothing to do.
+func (m Memory) Apply(root *cgroup.Group) (Groups, error) {
+	var g Groups
+	var err error
+	mib := func(n int64) int64 { return n << 20 }
+	if g.Broker, err = root.Component("broker", cgroup.Limits{MinBytes: mib(m.HostMB)}); err != nil {
+		return Groups{}, err
+	}
+	if m.InferenceMB > 0 {
+		if g.Inference, err = root.Component("inference", cgroup.Limits{MaxBytes: mib(m.InferenceMB)}); err != nil {
+			return Groups{}, err
+		}
+	}
+	if m.BrowserMB > 0 {
+		if g.Browser, err = root.Component("browser", cgroup.Limits{MaxBytes: mib(m.BrowserMB)}); err != nil {
+			return Groups{}, err
+		}
+	}
+	// The pool's own memory.high would throttle every machine together
+	// before any one reached its limit, so it is set at the hard limit:
+	// per-machine groups carry the throttle.
+	pool, err := root.Component("machines", cgroup.Limits{MaxBytes: mib(m.PoolMB), HighBytes: mib(m.PoolMB)})
+	if err != nil {
+		return Groups{}, err
+	}
+	if g.Machines, err = cgroup.Open(pool.Path); err != nil {
+		return Groups{}, err
+	}
+	return g, nil
+}
+
+// MemTotalMB reads MemTotal from a meminfo file (/proc/meminfo), in MiB.
+func MemTotalMB(path string) (int64, error) {
+	f, err := os.Open(path)
+	if err != nil {
+		return 0, err
+	}
+	defer f.Close()
+	s := bufio.NewScanner(f)
+	for s.Scan() {
+		if v, ok := strings.CutPrefix(s.Text(), "MemTotal:"); ok {
+			kb, err := strconv.ParseInt(strings.TrimSuffix(strings.TrimSpace(v), " kB"), 10, 64)
+			if err != nil {
+				return 0, fmt.Errorf("budget: %s: %w", path, err)
+			}
+			return kb >> 10, nil
+		}
+	}
+	if err := s.Err(); err != nil {
+		return 0, err
+	}
+	return 0, fmt.Errorf("budget: no MemTotal in %s", filepath.Clean(path))
+}
+
+// Disk is the state disk's RES-4 reserve, MiB: what must stay free before
+// any discretionary download or snapshot.
+type Disk struct {
+	ReleaseMB int64 // one healthy release staged before install (S7: 1.0 GiB erofs + 69 MiB verity)
+	JournalMB int64 // journal growth
+	RecallMB  int64 // recall index growth
+}
+
+// FloorDisk is the floor's reserve. Only the release figure is measured
+// (S7); the journal and recall figures are placeholders until P3 sizes them.
+func FloorDisk() Disk {
+	return Disk{ReleaseMB: 1280, JournalMB: 512, RecallMB: 1024}
+}
+
+// ReserveBytes is the whole reserve in bytes.
+func (d Disk) ReserveBytes() int64 { return (d.ReleaseMB + d.JournalMB + d.RecallMB) << 20 }
diff --git a/broker/budget/budget_test.go b/broker/budget/budget_test.go
new file mode 100644
index 000000000..45f30c388
--- /dev/null
+++ b/broker/budget/budget_test.go
@@ -0,0 +1,170 @@
+package budget
+
+import (
+	"fmt"
+	"os"
+	"path/filepath"
+	"strconv"
+	"strings"
+	"testing"
+
+	"github.com/ghbmrk/agentos/broker/cgroup"
+)
+
+// REQ: RES-2, RES-4
+
+func TestRES2FloorBudgetMatchesTheSpecTable(t *testing.T) {
+	f := Floor()
+	if f.HostMB != 1024 || f.InferenceMB != 2048 || f.BrowserMB != 512 || f.HeadroomMB != 600 {
+		t.Fatalf("floor = %+v, want SPEC RES-2's 1.0 / 2.0 / 0.5 GB and 0.6 GB headroom", f)
+	}
+}
+
+func TestRES2PoolIsWhatTheDeclaredComponentsLeave(t *testing.T) {
+	// An 8 GB N95 reports about 7.6 GiB: firmware and the iGPU take the rest.
+	m, err := ForHost(7680, Floor())
+	must(t, err)
+	if m.PoolMB != 7680-4184 {
+		t.Fatalf("pool = %d MiB", m.PoolMB)
+	}
+	if m.Total() != 7680 {
+		t.Fatalf("components sum to %d, want the host's memory", m.Total())
+	}
+	// Two OpenClaw-sized machines (S3, S4) fit at the floor; three do not.
+	if n := m.PoolMB / OpenClawMB; n != 2 {
+		t.Fatalf("pool holds %d OpenClaw machines, want 2", n)
+	}
+	a := m.Admission()
+	if a.CapacityMB-a.HeadroomMB != m.PoolMB || a.HeadroomMB != 600 {
+		t.Fatalf("admission %+v: admitted memory must be exactly the pool", a)
+	}
+}
+
+func TestRES2LargerHostsKeepEveryOtherBudget(t *testing.T) {
+	// HW-4: a larger host never changes the other budgets. Its pool grows
+	// up to MaxCapacityMB (PE6, R1 on #114), no further.
+	small, err := ForHost(7680, Floor())
+	must(t, err)
+	big, err := ForHost(32768, Floor())
+	must(t, err)
+	if big.HostMB != small.HostMB || big.InferenceMB != small.InferenceMB || big.BrowserMB != small.BrowserMB || big.HeadroomMB != small.HeadroomMB {
+		t.Fatalf("components changed with host size: %+v vs %+v", small, big)
+	}
+	if big.PoolMB != MaxCapacityMB-big.HeadroomMB || big.PoolMB <= small.PoolMB {
+		t.Fatalf("pool %d MiB on a large host, %d at the floor", big.PoolMB, small.PoolMB)
+	}
+}
+
+func TestRES2SmallHostPoolAndBadBudgets(t *testing.T) {
+	// A host too small for one machine gets the pool it has; agentosd turns
+	// the agent off and says so.
+	m, err := ForHost(5000, Floor())
+	must(t, err)
+	if m.PoolMB >= OpenClawMB {
+		t.Fatalf("5000 MiB host: pool %d MiB holds a machine", m.PoolMB)
+	}
+	bad := Floor()
+	bad.HeadroomMB = 0
+	if _, err := ForHost(7680, bad); err == nil {
+		t.Fatal("zero headroom accepted (S3: a group at its limit stalls)")
+	}
+}
+
+func TestRES2MemTotalReadsMeminfo(t *testing.T) {
+	p := filepath.Join(t.TempDir(), "meminfo")
+	must(t, os.WriteFile(p, []byte("MemTotal:        7864320 kB\nMemFree:  100 kB\n"), 0o644))
+	mb, err := MemTotalMB(p)
+	must(t, err)
+	if mb != 7680 {
+		t.Fatalf("MemTotal = %d MiB", mb)
+	}
+}
+
+func fakeV2(t *testing.T) *cgroup.Group {
+	t.Helper()
+	d := t.TempDir()
+	must(t, os.WriteFile(filepath.Join(d, "cgroup.controllers"), []byte("cpu memory pids\n"), 0o644))
+	must(t, os.WriteFile(filepath.Join(d, "cgroup.subtree_control"), nil, 0o644))
+	g, err := cgroup.Open(d)
+	must(t, err)
+	return g
+}
+
+func read(t *testing.T, p string) string {
+	t.Helper()
+	b, err := os.ReadFile(p)
+	must(t, err)
+	return strings.TrimSpace(string(b))
+}
+
+// Every component's limit is enforced by its own cgroup, and the limits plus
+// the broker's protection plus the headroom never exceed the host (RES-2).
+func TestRES2ApplyGivesEachComponentItsOwnGroup(t *testing.T) {
+	root := fakeV2(t)
+	m, err := ForHost(7680, Floor())
+	must(t, err)
+	// The pool's group must accept per-machine children: the kernel lists
+	// the memory controller in its cgroup.controllers once the parent's
+	// subtree_control enables it, which the fake plays here.
+	pool := filepath.Join(root.Path, "machines")
+	must(t, os.MkdirAll(pool, 0o755))
+	must(t, os.WriteFile(filepath.Join(pool, "cgroup.controllers"), []byte("memory\n"), 0o644))
+	must(t, os.WriteFile(filepath.Join(pool, "cgroup.subtree_control"), nil, 0o644))
+
+	gs, err := m.Apply(root)
+	must(t, err)
+	mib := func(n int64) string { return strconv.FormatInt(n<<20, 10) }
+	for _, c := range []struct{ group, file, want string }{
+		{"broker", "memory.min", mib(1024)},
+		{"broker", "memory.max", "max"},
+		{"inference", "memory.max", mib(2048)},
+		{"browser", "memory.max", mib(512)},
+		{"machines", "memory.max", mib(m.PoolMB)},
+	} {
+		if got := read(t, filepath.Join(root.Path, c.group, c.file)); got != c.want {
+			t.Errorf("%s/%s = %s, want %s", c.group, c.file, got, c.want)
+		}
+	}
+	if gs.Machines == nil || gs.Machines.Path != pool {
+		t.Fatalf("machines group = %+v", gs.Machines)
+	}
+	if got := read(t, filepath.Join(pool, "cgroup.subtree_control")); got != "+memory" {
+		t.Fatalf("pool children cannot use the memory controller: %q", got)
+	}
+}
+
+func TestRES4DiskReserveCoversReleaseJournalAndRecall(t *testing.T) {
+	d := FloorDisk()
+	if d.ReleaseMB < 1100 {
+		t.Fatalf("release reserve %d MiB is smaller than one S7 release (1.0 GiB erofs + verity)", d.ReleaseMB)
+	}
+	if d.JournalMB <= 0 || d.RecallMB <= 0 {
+		t.Fatalf("disk reserve %+v leaves out the journal or the recall index", d)
+	}
+	if d.ReserveBytes() != (d.ReleaseMB+d.JournalMB+d.RecallMB)<<20 {
+		t.Fatalf("reserve = %d", d.ReserveBytes())
+	}
+}
+
+func must(t *testing.T, err error) {
+	t.Helper()
+	if err != nil {
+		t.Fatal(err)
+	}
+}
+
+// The S1 test kit's floor_fit reports the same floor budget the broker
+// applies (P2-5r: one source for it), so the N95 reading checks the real
+// figures.
+func TestRES2TestKitUsesTheSameFloor(t *testing.T) {
+	b, err := os.ReadFile(filepath.Join("..", "..", "spikes", "S1S2-testkit", "mkosi", "mkosi.extra", "usr", "lib", "testkit", "testkit.py"))
+	must(t, err)
+	f := Floor()
+	want := fmt.Sprintf(`FLOOR = {"host": %d, "inference": %d, "browser": %d, "headroom": %d}`, f.HostMB, f.InferenceMB, f.BrowserMB, f.HeadroomMB)
+	if !strings.Contains(string(b), want) {
+		t.Fatalf("testkit.py has no %s", want)
+	}
+	if !strings.Contains(string(b), fmt.Sprintf("min(pool + FLOOR[\"headroom\"], %d)", MaxCapacityMB)) {
+		t.Fatalf("testkit.py does not cap capacity at %d", MaxCapacityMB)
+	}
+}
