diff --git a/broker/cgroup/component.go b/broker/cgroup/component.go
new file mode 100644
index 000000000..5eddfe519
--- /dev/null
+++ b/broker/cgroup/component.go
@@ -0,0 +1,76 @@
+package cgroup
+
+import (
+	"errors"
+	"fmt"
+	"os"
+	"path/filepath"
+	"strconv"
+	"strings"
+)
+
+// Component creates (or reuses) the group of one of the host's declared
+// components (RES-2): the broker, local inference, the credentialed browser,
+// or the agent-machine pool. A component with MaxBytes gets a hard limit
+// with memory.high 1/16 below it, as machines do. A component with only
+// MinBytes gets no hard limit and protected memory instead: that is the
+// broker, which must never be OOM-killed by its own group or lose its pages
+// to reclaim. Unlike Child, memory.oom.group stays off, because a component
+// holds independent children (the pool holds every machine).
+func (g *Group) Component(name string, l Limits) (*Group, error) {
+	if name == "" || strings.ContainsAny(name, "/.") {
+		return nil, fmt.Errorf("cgroup: bad group name %q", name)
+	}
+	if l.MaxBytes <= 0 && l.MinBytes <= 0 {
+		return nil, fmt.Errorf("cgroup: %s: a budget or a protection is required (RES-2)", name)
+	}
+	c := &Group{Path: filepath.Join(g.Path, name)}
+	if err := os.Mkdir(c.Path, 0o755); err != nil && !errors.Is(err, os.ErrExist) {
+		return nil, err
+	}
+	var kvs [][2]string
+	if l.MaxBytes > 0 {
+		high := l.HighBytes
+		if high <= 0 || high > l.MaxBytes {
+			high = l.MaxBytes - l.MaxBytes/16
+		}
+		kvs = append(kvs,
+			[2]string{"memory.max", strconv.FormatInt(l.MaxBytes, 10)},
+			[2]string{"memory.high", strconv.FormatInt(high, 10)})
+	} else {
+		kvs = append(kvs, [2]string{"memory.max", "max"})
+	}
+	if l.MinBytes > 0 {
+		kvs = append(kvs, [2]string{"memory.min", strconv.FormatInt(l.MinBytes, 10)})
+	}
+	kvs = append(kvs, [2]string{"memory.swap.max", "0"})
+	for _, kv := range kvs {
+		if err := c.write(kv[0], kv[1]); err != nil {
+			if kv[0] == "memory.swap.max" && errors.Is(err, os.ErrNotExist) {
+				continue // no swap accounting: there is no swap to use
+			}
+			return nil, err
+		}
+	}
+	return c, nil
+}
+
+// Join moves process pid into the group.
+func (g *Group) Join(pid int) error {
+	return g.write("cgroup.procs", strconv.Itoa(pid))
+}
+
+// OOMKills is the number of processes the kernel has OOM-killed in the group
+// and its descendants (memory.events oom_kill).
+func (g *Group) OOMKills() (int64, error) {
+	b, err := os.ReadFile(filepath.Join(g.Path, "memory.events"))
+	if err != nil {
+		return 0, err
+	}
+	for _, line := range strings.Split(string(b), "\n") {
+		if v, ok := strings.CutPrefix(line, "oom_kill "); ok {
+			return strconv.ParseInt(strings.TrimSpace(v), 10, 64)
+		}
+	}
+	return 0, fmt.Errorf("cgroup: no oom_kill in %s/memory.events", g.Path)
+}
diff --git a/broker/cgroup/component_test.go b/broker/cgroup/component_test.go
new file mode 100644
index 000000000..1870e32e6
--- /dev/null
+++ b/broker/cgroup/component_test.go
@@ -0,0 +1,78 @@
+package cgroup
+
+import (
+	"os"
+	"path/filepath"
+	"strconv"
+	"testing"
+)
+
+// REQ: RES-2
+
+func TestRES2ComponentHardLimitWithoutGroupOOMKill(t *testing.T) {
+	g := fakeV2(t)
+	c, err := g.Component("inference", Limits{MaxBytes: 2000 << 20})
+	must(t, err)
+	if got := read(t, filepath.Join(c.Path, "memory.max")); got != strconv.Itoa(2000<<20) {
+		t.Errorf("memory.max = %s", got)
+	}
+	if got := read(t, filepath.Join(c.Path, "memory.high")); got != strconv.Itoa(2000<<20-2000<<20/16) {
+		t.Errorf("memory.high = %s, want max - 1/16", got)
+	}
+	if got := read(t, filepath.Join(c.Path, "memory.swap.max")); got != "0" {
+		t.Errorf("memory.swap.max = %s, want 0", got)
+	}
+	// A component holds many independent children (the machine pool holds
+	// every machine), so an OOM in it must not take all of them at once.
+	if _, err := os.Stat(filepath.Join(c.Path, "memory.oom.group")); err == nil {
+		t.Errorf("memory.oom.group written on a component group")
+	}
+}
+
+func TestRES2ProtectedComponentHasNoHardLimitAndIsNotReclaimed(t *testing.T) {
+	g := fakeV2(t)
+	c, err := g.Component("broker", Limits{MinBytes: 1000 << 20})
+	must(t, err)
+	if got := read(t, filepath.Join(c.Path, "memory.min")); got != strconv.Itoa(1000<<20) {
+		t.Errorf("memory.min = %s, want the broker's budget protected from reclaim", got)
+	}
+	// No hard limit: the broker is never OOM-killed by its own group
+	// (RES-2); it is everything else that is capped.
+	if got := read(t, filepath.Join(c.Path, "memory.max")); got != "max" {
+		t.Errorf("memory.max = %s, want max", got)
+	}
+	if _, err := os.Stat(filepath.Join(c.Path, "memory.high")); err == nil {
+		t.Errorf("memory.high written on a protected component")
+	}
+}
+
+func TestRES2ComponentNeedsALimitOrAProtection(t *testing.T) {
+	g := fakeV2(t)
+	if _, err := g.Component("x", Limits{}); err == nil {
+		t.Fatal("component with neither max nor min accepted")
+	}
+	if _, err := g.Component("../x", Limits{MaxBytes: 1}); err == nil {
+		t.Fatal("bad name accepted")
+	}
+}
+
+func TestRES2JoinMovesAProcess(t *testing.T) {
+	g := fakeV2(t)
+	c, err := g.Component("broker", Limits{MinBytes: 1 << 20})
+	must(t, err)
+	must(t, c.Join(4242))
+	if got := read(t, filepath.Join(c.Path, "cgroup.procs")); got != "4242" {
+		t.Errorf("cgroup.procs = %q", got)
+	}
+}
+
+func TestRES2OOMKillsReadsMemoryEvents(t *testing.T) {
+	g := fakeV2(t)
+	must(t, os.WriteFile(filepath.Join(g.Path, "memory.events"),
+		[]byte("low 0\nhigh 12\nmax 0\noom 1\noom_kill 3\noom_group_kill 0\n"), 0o644))
+	n, err := g.OOMKills()
+	must(t, err)
+	if n != 3 {
+		t.Fatalf("OOMKills = %d, want 3", n)
+	}
+}
diff --git a/broker/cmd/agentosd/cgroot.go b/broker/cmd/agentosd/cgroot.go
new file mode 100644
index 000000000..c3437ae38
--- /dev/null
+++ b/broker/cmd/agentosd/cgroot.go
@@ -0,0 +1,76 @@
+package main
+
+import (
+	"errors"
+	"fmt"
+	"os"
+	"path/filepath"
+	"strings"
+
+	"github.com/ghbmrk/agentos/broker/budget"
+	"github.com/ghbmrk/agentos/broker/cgroup"
+)
+
+// agentNoMemControls is STATUS's agent line when the broker may not manage
+// the box's cgroups, so no machine may start (RES-2: none runs unbudgeted).
+const agentNoMemControls = "Agent: off, the box's memory controls are not set up; it needs an update."
+
+// cgroupHost is where the broker reads its cgroup facts; tests point it at
+// a fake cgroupfs.
+type cgroupHost struct {
+	FS        string            // cgroup v2 mount, /sys/fs/cgroup
+	ProcSelf  string            // /proc/self/cgroup
+	Delegated func(string) bool // the group carries systemd's delegate mark
+}
+
+var liveCgroups = cgroupHost{FS: "/sys/fs/cgroup", ProcSelf: "/proc/self/cgroup", Delegated: delegateMarked}
+
+// errNotDelegated means the broker has no proof the group is its own to
+// manage. Writing outside a delegated subtree could move or limit other
+// processes on the box, so the broker refuses rather than guesses.
+var errNotDelegated = errors.New("cgroup not delegated to the broker")
+
+// delegatedRoot is the group the broker may manage: its own cgroup or one
+// beneath it, and only with proof of delegation: systemd's delegate mark on
+// the broker's own group (Delegate=yes), or an explicit root that the
+// operator vouches for with -cgroup-delegated. It reads and writes nothing
+// under the cgroupfs.
+func delegatedRoot(h cgroupHost, flagRoot string, vouched bool) (string, error) {
+	b, err := os.ReadFile(h.ProcSelf)
+	if err != nil {
+		return "", err
+	}
+	rel, ok := "", false
+	for _, line := range strings.Split(string(b), "\n") {
+		if v, found := strings.CutPrefix(line, "0::"); found {
+			rel, ok = v, true
+			break
+		}
+	}
+	if !ok || !strings.HasPrefix(rel, "/") {
+		return "", fmt.Errorf("%w: no cgroup v2 entry in %s", errNotDelegated, h.ProcSelf)
+	}
+	own := filepath.Join(h.FS, rel)
+	root := own
+	if flagRoot != "" {
+		root = filepath.Clean(flagRoot)
+	}
+	if root != own && !strings.HasPrefix(root, own+"/") {
+		return "", fmt.Errorf("%w: %s is outside the broker's own group %s", errNotDelegated, root, own)
+	}
+	if (vouched && flagRoot != "") || (h.Delegated != nil && h.Delegated(own)) {
+		return root, nil
+	}
+	return "", fmt.Errorf("%w: %s has no delegate mark (run under systemd Delegate=yes, or pass -cgroup-root with -cgroup-delegated)", errNotDelegated, own)
+}
+
+// openMachines finds the delegated root and applies the component budget
+// there. Any failure leaves the cgroupfs untouched by delegatedRoot and
+// machines off.
+func openMachines(h cgroupHost, flagRoot string, vouched bool, mem budget.Memory) (*cgroup.Group, error) {
+	root, err := delegatedRoot(h, flagRoot, vouched)
+	if err != nil {
+		return nil, err
+	}
+	return openPool(root, mem)
+}
