new file mode 100644
index 000000000..1e84d89fa
--- /dev/null
+++ b/broker/vm/preempt_test.go
@@ -0,0 +1,146 @@
+package vm
+
+import (
+	"context"
+	"errors"
+	"testing"
+	"time"
+
+	"github.com/ghbmrk/agentos/broker/admission"
+)
+
+// REQ: RES-1
+
+// slowRuntime blocks Checkpoint or Restore until released, standing in for
+// a 2-4.5 s checkpoint or restore of an OpenClaw-sized guest (S3).
+type slowRuntime struct {
+	*fakeRuntime
+	block   chan struct{} // closed to release
+	entered chan string   // receives the blocked call's name
+	what    string        // "checkpoint" or "restore"
+}
+
+func (s *slowRuntime) wait(what string) {
+	if s.what == what {
+		s.entered <- what
+		<-s.block
+	}
+}
+
+func (s *slowRuntime) Checkpoint(ctx context.Context, id, image string) error {
+	s.wait("checkpoint")
+	return s.fakeRuntime.Checkpoint(ctx, id, image)
+}
+
+func (s *slowRuntime) Restore(ctx context.Context, l Launch, image string) error {
+	s.wait("restore")
+	return s.fakeRuntime.Restore(ctx, l, image)
+}
+
+func slowEnv(t *testing.T, what string) (*env, *slowRuntime) {
+	e := newEnv(t, 2000)
+	s := &slowRuntime{fakeRuntime: e.rt, block: make(chan struct{}), entered: make(chan string, 1), what: what}
+	e.cfg.Runtime = s
+	e.open()
+	return e, s
+}
+
+// The frozen target (RES-1) is shorter than a full checkpoint, so
+// preemption must not wait for an operation already holding the
+// experiment: it kills the sandbox under it.
+func TestRES1PreemptionDoesNotWaitForACheckpointInProgress(t *testing.T) {
+	e, s := slowEnv(t, "checkpoint")
+	e.create("exp", admission.Experiment, 1500)
+	ckpt := make(chan error, 1)
+	go func() { _, err := e.m.Checkpoint(bg, "exp"); ckpt <- err }()
+	<-s.entered // the checkpoint holds the machine now
+
+	start := time.Now()
+	done := make(chan error, 1)
+	go func() {
+		_, err := e.m.Create(bg, "call", Spec{Image: "base", Class: admission.Foreground, MemMB: 1000})
+		done <- err
+	}()
+	select {
+	case err := <-done:
+		must(t, err)
+	case <-time.After(2 * time.Second):
+		close(s.block)
+		t.Fatal("foreground admission waited for the experiment's checkpoint")
+	}
+	t.Logf("preemption under a running checkpoint took %v (fake runtime)", time.Since(start))
+	if _, ok := e.rt.memOf("exp"); ok {
+		t.Fatal("experiment still running after preemption returned")
+	}
+	close(s.block)
+	if err := <-ckpt; err == nil {
+		t.Fatal("checkpoint of a killed machine reported success")
+	}
+	waitState(t, e, "exp", Preempted)
+	if _, ok := e.rt.memOf("exp"); ok {
+		t.Fatal("experiment running again after its checkpoint unwound")
+	}
+	// It resumes as usual once there is room.
+	must(t, e.m.Destroy(bg, "call"))
+	must(t, e.m.Resume(bg, "exp"))
+}
+
+// A rollback that was already restoring when preemption hit must not bring
+// the machine back to life on memory admission has handed to someone else.
+func TestRES1InterruptedRollbackDoesNotRestartThePreemptedMachine(t *testing.T) {
+	e, s := slowEnv(t, "")
+	e.create("exp", admission.Experiment, 1500)
+	snap, err := e.m.Checkpoint(bg, "exp")
+	must(t, err)
+	s.what = "restore"
+	rb := make(chan error, 1)
+	go func() { rb <- e.m.Rollback(bg, "exp", snap.ID) }()
+	<-s.entered // the rollback is restoring memory now
+
+	done := make(chan error, 1)
+	go func() {
+		_, err := e.m.Create(bg, "call", Spec{Image: "base", Class: admission.Foreground, MemMB: 1000})
+		done <- err
+	}()
+	select {
+	case err := <-done:
+		if err != nil {
+			close(s.block)
+			t.Fatal(err)
+		}
+	case <-time.After(2 * time.Second):
+		close(s.block)
+		t.Fatal("foreground admission waited for the experiment's rollback")
+	}
+	close(s.block)
+	if err := <-rb; !errors.Is(err, ErrRevoked) {
+		t.Fatalf("rollback after preemption: %v, want ErrRevoked", err)
+	}
+	if _, ok := e.rt.memOf("exp"); ok {
+		t.Fatal("the interrupted rollback restarted the preempted machine")
+	}
+	if got := e.adm.Snapshot().Running; len(got) != 1 {
+		t.Fatalf("admitted: %v, want only the call", got)
+	}
+	mc, err := e.m.Get("exp")
+	must(t, err)
+	if mc.State == Running {
+		t.Fatal("experiment recorded as running")
+	}
+}
+
+func waitState(t *testing.T, e *env, id string, want State) {
+	t.Helper()
+	deadline := time.Now().Add(2 * time.Second)
+	for {
+		mc, err := e.m.Get(id)
+		must(t, err)
+		if mc.State == want {
+			return
+		}
+		if time.Now().After(deadline) {
+			t.Fatalf("%s is %s, want %s", id, mc.State, want)
+		}
+		time.Sleep(5 * time.Millisecond)
+	}
+}
diff --git a/broker/vm/prune.go b/broker/vm/prune.go
new file mode 100644
index 000000000..5776053c9
--- /dev/null
+++ b/broker/vm/prune.go
@@ -0,0 +1,181 @@
+package vm
+
+import (
+	"log"
+	"os"
+	"path/filepath"
+	"sort"
+	"time"
+)
+
+// PrunePolicy says which snapshots are kept (RES-4). Zero fields take the
+// defaults.
+type PrunePolicy struct {
+	KeepFS   int // newest file-system snapshots kept per machine (default 50)
+	KeepFull int // newest full checkpoints kept per machine (default 2)
+	// MinAge protects snapshots younger than this (default 10 min), so a
+	// fork or merge between taking a snapshot and recording its use never
+	// loses it.
+	MinAge time.Duration
+	// LowWaterBytes: while the state disk's free space is below the RES-4
+	// reserve plus this, every machine keeps only the essentials.
+	LowWaterBytes int64
+}
+
+func (p PrunePolicy) withDefaults() PrunePolicy {
+	if p.KeepFS <= 0 {
+		p.KeepFS = 50
+	}
+	if p.KeepFull <= 0 {
+		p.KeepFull = 2
+	}
+	if p.MinAge <= 0 {
+		p.MinAge = 10 * time.Minute
+	}
+	return p
+}
+
+func (m *Manager) clock() time.Time {
+	if m.now != nil {
+		return m.now()
+	}
+	return time.Now()
+}
+
+// Prune deletes the snapshots policy p no longer keeps and returns their
+// IDs. Never pruned: a live machine's newest snapshot, its oldest full
+// checkpoint (the warm template, REV-1) and its newest one; any snapshot a
+// live machine was forked from (rollback and merge need it); and anything
+// younger than MinAge. Beyond those, each live machine keeps its KeepFS
+// newest file-system snapshots and KeepFull newest checkpoints; under disk
+// pressure it keeps only the protected ones. A destroyed machine's
+// snapshots no longer serve any rollback, so only the protections above
+// keep them.
+//
+// Prune holds each live machine's lock while deleting its snapshots, so no
+// rollback of that machine runs meanwhile; preemption does not wait for
+// that lock (Preempt).
+func (m *Manager) Prune(p PrunePolicy) ([]string, error) {
+	p = p.withDefaults()
+	pressured := false
+	if p.LowWaterBytes > 0 {
+		free, err := m.cfg.FreeBytes(m.cfg.StateDir)
+		if err != nil {
+			return nil, err
+		}
+		pressured = free < m.cfg.DiskReserveBytes+p.LowWaterBytes
+	}
+
+	m.mu.Lock()
+	live := map[string]*machine{}
+	for id, mc := range m.machines {
+		live[id] = mc
+	}
+	byMachine := map[string][]Snapshot{}
+	for _, s := range m.snaps {
+		byMachine[s.Machine] = append(byMachine[s.Machine], s)
+	}
+	m.mu.Unlock()
+
+	forkBases := map[string]bool{}
+	for _, mc := range live {
+		mc.mu.Lock()
+		if mc.ForkBase != "" {
+			forkBases[mc.ForkBase] = true
+		}
+		mc.mu.Unlock()
+	}
+
+	cutoff := m.clock().Add(-p.MinAge)
+	var gone, dirs []string
+	var firstErr error
+	owners := make([]string, 0, len(byMachine))
+	for id := range byMachine {
+		owners = append(owners, id)
+	}
+	sort.Strings(owners)
+	for _, owner := range owners {
+		snaps := byMachine[owner]
+		sort.Slice(snaps, func(i, j int) bool { return snaps[i].ID > snaps[j].ID }) // newest first
+		mc := live[owner]
+		if mc != nil {
+			mc.mu.Lock()
+		}
+		keep := map[string]bool{}
+		if mc != nil {
+			keep[mc.Last] = true
+			nFS, nFull := 0, 0
+			var oldestFull string
+			for _, s := range snaps {
+				switch s.Tier {
+				case FS:
+					if nFS < p.KeepFS && !pressured {
+						keep[s.ID] = true
+					}
+					nFS++
+				case Full:
+					if nFull == 0 || (nFull < p.KeepFull && !pressured) {
+						keep[s.ID] = true
+					}
+					nFull++
+					oldestFull = s.ID
+				}
+			}
+			keep[oldestFull] = true
+		}
+		for _, s := range snaps {
+			if keep[s.ID] || forkBases[s.ID] || !s.Taken.Before(cutoff) {
+				continue
+			}
+			if err := m.unpublishSnapshot(s.ID); err != nil {
+				if firstErr == nil {
+					firstErr = err
+				}
+				continue
+			}
+			gone = append(gone, s.ID)
+			dirs = append(dirs, m.snapDir(s.ID))
+		}
+		if mc != nil {
+			mc.mu.Unlock()
+		}
+	}
+	// The files go outside the machine's lock (L3 on #124): unpublished
+	// snapshots are found by no rollback, fork, or merge.
+	for _, dir := range dirs {
+		if err := os.RemoveAll(dir); err != nil && firstErr == nil {
+			firstErr = err
+		}
+	}
+	sort.Strings(gone)
+	return gone, firstErr
+}
+
+// unpublishSnapshot unpublishes a snapshot: its record first, then its
+// metadata, so a crash leaves a directory that load drops. The caller
+// deletes the directory.
+func (m *Manager) unpublishSnapshot(id string) error {
+	m.mu.Lock()
+	delete(m.snaps, id)
+	m.mu.Unlock()
+	if err := os.Remove(filepath.Join(m.snapDir(id), "meta.json")); err != nil && !os.IsNotExist(err) {
+		return err
+	}
+	return nil
+}
+
+// RunPruner prunes by p every interval until stop is closed.
+func (m *Manager) RunPruner(p PrunePolicy, interval time.Duration, stop <-chan struct{}) {
+	t := time.NewTicker(interval)
+	defer t.Stop()
+	for {
+		if _, err := m.Prune(p); err != nil {
+			log.Printf("vm: pruning snapshots: %v", err)
+		}
+		select {
+		case <-stop:
+			return
+		case <-t.C:
+		}
+	}
+}
diff --git a/broker/vm/prune_test.go b/broker/vm/prune_test.go
new file mode 100644
index 000000000..938e38283
--- /dev/null
+++ b/broker/vm/prune_test.go
@@ -0,0 +1,175 @@
+package vm
+
+import (
+	"os"
+	"path/filepath"
+	"testing"
+	"time"
+
+	"github.com/ghbmrk/agentos/broker/admission"
+)
+
+// REQ: RES-4
+
+func ids(ss []Snapshot) []string {
+	var out []string
+	for _, s := range ss {
+		out = append(out, s.ID)
+	}
+	return out
+}
+
+func has(ss []Snapshot, id string) bool {
+	for _, s := range ss {
+		if s.ID == id {
+			return true
+		}
+	}
+	return false
+}
+
+// pruneEnv ages every snapshot past MinAge so the policy alone decides.
+func pruneEnv(t *testing.T) *env {
+	e := newEnv(t, 8000)
+	e.m.now = func() time.Time { return time.Now().Add(time.Hour) }
+	return e
+}
+
+func TestRES4PrunePolicyKeepsNewestAndTemplatesAndDropsTheRest(t *testing.T) {
+	e := pruneEnv(t)
+	e.create("m", admission.Accepted, 100)
+	tmpl, err := e.m.Checkpoint(bg, "m") // warm template
+	must(t, err)
+	var steps []Snapshot
+	for i := 0; i < 6; i++ {
+		s, err := e.m.Step(bg, "m")
+		must(t, err)
+		steps = append(steps, s)
+	}
+	mid, err := e.m.Checkpoint(bg, "m")
+	must(t, err)
+	last, err := e.m.Checkpoint(bg, "m")
+	must(t, err)
+
+	gone, err := e.m.Prune(PrunePolicy{KeepFS: 2, KeepFull: 1})
+	must(t, err)
+	left := e.m.Snapshots("m")
+	for _, keep := range []string{tmpl.ID, last.ID, steps[4].ID, steps[5].ID} {
+		if !has(left, keep) {
+			t.Errorf("pruned %s; left %v", keep, ids(left))
+		}
+	}
+	for _, drop := range []string{steps[0].ID, steps[3].ID, mid.ID} {
+		if has(left, drop) {
+			t.Errorf("kept %s beyond policy", drop)
+		}
+		if _, err := os.Stat(filepath.Join(e.cfg.StateDir, "snapshots", drop)); !os.IsNotExist(err) {
+			t.Errorf("%s still on disk", drop)
+		}
+	}
+	if len(gone) != 5 {
+		t.Errorf("pruned %v, want 5", gone)
+	}
+	// The machine still rolls back to what was kept.
+	must(t, e.m.Rollback(bg, "m", tmpl.ID))
+	// Pruned snapshots stay gone across a broker restart.
+	e.open()
+	if got := e.m.Snapshots("m"); len(got) != len(left) {
+		t.Fatalf("after restart: %v, want %v", ids(got), ids(left))
+	}
+}
+
+func TestRES4ForkBasesAndFreshSnapshotsAreNeverPruned(t *testing.T) {
+	e := newEnv(t, 8000)
+	e.create("src", admission.Accepted, 100)
+	_, err := e.m.Checkpoint(bg, "src") // warm template
+	must(t, err)
+	base, err := e.m.Fork(bg, "src", []string{"f1"})
+	must(t, err)
+	for i := 0; i < 3; i++ {
+		_, err := e.m.Step(bg, "src")
+		must(t, err)
+	}
+	_, err = e.m.Checkpoint(bg, "src") // newest full: base is neither end
+	must(t, err)
+	// Everything is fresh: nothing goes, whatever the policy.
+	if gone, _ := e.m.Prune(PrunePolicy{KeepFS: 1, KeepFull: 1}); len(gone) != 0 {
+		t.Fatalf("pruned fresh snapshots %v", gone)
+	}
+	e.m.now = func() time.Time { return time.Now().Add(time.Hour) }
+	if _, err := e.m.Prune(PrunePolicy{KeepFS: 1, KeepFull: 1}); err != nil {
+		t.Fatal(err)
+	}
+	if _, err := e.m.Snapshot(base.ID); err != nil {
+		t.Fatal("pruned the snapshot a live fork was made from (merge needs it)")
+	}
+	// Once the fork is gone, its base is ordinary history again.
+	must(t, e.m.Destroy(bg, "f1"))
+	if _, err := e.m.Prune(PrunePolicy{KeepFS: 1, KeepFull: 1}); err != nil {
+		t.Fatal(err)
+	}
+	if _, err := e.m.Snapshot(base.ID); err == nil {
+		t.Fatal("kept a fork base no machine uses")
+	}
+}
+
+func TestRES4DestroyedMachinesSnapshotsArePruned(t *testing.T) {
+	e := pruneEnv(t)
+	e.create("tmp", admission.Experiment, 100)
+	_, err := e.m.Checkpoint(bg, "tmp")
+	must(t, err)
+	_, err = e.m.Step(bg, "tmp")
+	must(t, err)
+	must(t, e.m.Destroy(bg, "tmp"))
+	if _, err := e.m.Prune(PrunePolicy{}); err != nil {
+		t.Fatal(err)
+	}
+	if left := e.m.Snapshots("tmp"); len(left) != 0 {
+		t.Fatalf("destroyed machine's snapshots kept: %v", ids(left))
+	}
+}
+
+// Under disk pressure the policy tightens to each machine's newest
+// snapshot and its templates, before the reserve is touched.
+func TestRES4PressurePrunesDownToTheEssentials(t *testing.T) {
+	e := pruneEnv(t)
+	e.create("m", admission.Accepted, 100)
+	tmpl, err := e.m.Checkpoint(bg, "m")
+	must(t, err)
+	var last Snapshot
+	for i := 0; i < 4; i++ {
+		last, err = e.m.Step(bg, "m")
+		must(t, err)
+	}
+	e.m.cfg.DiskReserveBytes = 1 << 30
+	e.m.cfg.FreeBytes = func(string) (int64, error) { return 1<<30 + 10, nil } // under the low water
+	if _, err := e.m.Prune(PrunePolicy{KeepFS: 50, KeepFull: 5, LowWaterBytes: 1 << 20}); err != nil {
+		t.Fatal(err)
+	}
+	left := e.m.Snapshots("m")
+	if len(left) != 2 || !has(left, tmpl.ID) || !has(left, last.ID) {
+		t.Fatalf("under pressure kept %v, want the template and the newest", ids(left))
+	}
+}
+
+// A symlink inside a pruned snapshot is removed, never followed: what it
+// points at outside the state directory survives.
+func TestRES4PruneDoesNotFollowSymlinks(t *testing.T) {
+	e := pruneEnv(t)
+	e.create("tmp", admission.Experiment, 100)
+	s, err := e.m.Step(bg, "tmp")
+	must(t, err)
+	outside := filepath.Join(t.TempDir(), "keep")
+	must(t, os.MkdirAll(outside, 0o755))
+	must(t, os.WriteFile(filepath.Join(outside, "f"), []byte("x"), 0o644))
+	must(t, os.Symlink(outside, filepath.Join(e.cfg.StateDir, "snapshots", s.ID, "link")))
+	must(t, e.m.Destroy(bg, "tmp"))
+	gone, err := e.m.Prune(PrunePolicy{})
+	must(t, err)
+	if len(gone) != 1 {
+		t.Fatalf("pruned %v, want %s", gone, s.ID)
+	}
+	if _, err := os.Stat(filepath.Join(outside, "f")); err != nil {
+		t.Fatalf("prune followed a symlink: %v", err)
+	}
+}
